    if gcd(dt, M) == 1:
        a = (dc * pow(dt, -1, M)) % M
        b = (c2 - a * t2) % M
        p1 = (a * t1 + b) % M
        out.append(f"LINEAR a={a} b={b} pred1={p1:06d} actual1={c1:06d} MATCH={p1==c1}")
    # 2) LCG chain code->code (state = code itself), classic param sets, several extraction shifts
