    for (A,C,Mod) in lcg_sets:
        nx = (A*c2 + C) % Mod
        for sh in (0,4,8,16):
            if (nx >> sh) % M == c3:
                out.append(f"LCG-CHAIN MATCH {A},{C},2^{Mod.bit_length()-1}>>{sh}: {c2}->{c3}")
    # 3) hash-of-time prefixes (md5/sha1/sha256 over str(ts) and f"{ts}"), ts window +-5s
